#include "material_library_model.hpp"
#include "material_library_store.hpp"
#include "material_library_page.hpp"
#include <QtWidgets>
#include <QTest>
#include <iostream>
static void check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
template<class F>void refuses(F f){bool failed=false;try{f();}catch(...){failed=true;}check(failed,"expected refusal");}
static QJsonObject descriptor(QString kind,QString id,QString text){return {{"kind",kind},{"id",id},{"row",QJsonObject{{"id",id},{"title","材料"+id},{"text",text},{"originalText","原始正文"},{"author","测试作者"},{"sourceType","article"},{"topic","原主题"},{"publishedAt","2000-01-01"},{"updatedAt","2000-01-01"},{"legacyOriginal",QJsonObject{{"id",123}}}}}};}
static void ready(QWidget* page,const char* property){page->show();QElapsedTimer timer;timer.start();while(!page->property(property).toBool()&&timer.elapsed()<15000)QTest::qWait(10);check(page->property(property).toBool(),"asynchronous initial snapshot ready");}
int main(int argc,char**argv){QApplication app(argc,argv);try{auto d=descriptor("docs","same","完整原文");auto c=descriptor("collections","same","不同类型同ID");auto m=materialLibrary::material(d);auto ref=m.value("reference").toObject();check(materialLibrary::materials({d,c}).size()==2,"kind namespace");refuses([&]{materialLibrary::materials({d,d});});refuses([&]{materialLibrary::resolve(ref,{d,d});});check(materialLibrary::resolve(ref,{d})==d.value("row").toObject(),"unchanged docs exact sourceKind normalization");auto urlD=d;auto urlRow=d.value("row").toObject();urlRow["sourceUrl"]="https://example.com/article?id=1";urlD["row"]=urlRow;auto urlRef=materialLibrary::material(urlD).value("reference").toObject();urlRow["sourceUrl"]="https://example.com/article?id=2";urlD["row"]=urlRow;refuses([&]{materialLibrary::resolve(urlRef,{urlD});});auto changed=d;auto row=d.value("row").toObject();row["text"]="changed";changed["row"]=row;refuses([&]{materialLibrary::resolve(ref,{changed});});refuses([&]{materialLibrary::resolve(ref,{});});QJsonArray all;for(int i=0;i<601;++i)all.append(descriptor("docs",QString::number(i),QString("尾段%1").arg(i)));auto material=materialLibrary::materials(all);check(materialLibrary::filter(material,{{"search","尾段600"}},{}).size()==1,"full beyond500 search");auto r=materialLibrary::classification(ref,"人工观察",{"tag;literal"},"完整笔记","");materialLibrary::validate(r);refuses([&]{materialLibrary::classification(ref,"",{"重复","重复"},"","");});QTemporaryDir dir;MaterialLibraryStore store(dir.path()+"/side.sqlite");store.save(r,"");auto newer=materialLibrary::classification(ref,"后续分类",{},"新笔记",r.value("id").toString());store.save(newer,r.value("id").toString());refuses([&]{store.save(r,"");});auto oldBackup=QJsonObject{{"schema","material-library-v1"},{"records",QJsonArray{r}},{"heads",QJsonObject{{materialLibrary::key(ref),r.value("id")}}}};auto preview=store.preview(materialLibrary::bytes(oldBackup));check(store.history().size()==2,"preview readonly/cancel");store.merge(preview);check(store.heads().value(materialLibrary::key(ref)).toObject()==newer,"old import keeps current classification");MaterialLibraryStore restored(dir.path()+"/restored.sqlite");restored.merge(restored.preview(store.backup()));check(restored.history().size()==2,"full durable classification history");auto rev=store.saveState({{"notes","draft"}},"");refuses([&]{store.saveState({},"stale");});check(restored.state().isEmpty()&&store.state().value("revision")==rev,"private CAS not exported");if(argc>1){QFile f(QString::fromLocal8Bit(argv[1]));check(f.open(QIODevice::ReadOnly),"Java fixture");check(QJsonDocument::fromJson(f.readAll()).object()==r,"Java exact classification fingerprint");}auto ui=materialLibraryPage(dir.path()+"/ui.sqlite",nullptr,[=]{return all;});ready(ui,"materialSnapshotReady");auto list=ui->findChild<QListWidget*>("materialLibraryRows");check(list->count()==20,"actual bounded list");ui->findChild<QLineEdit*>("materialLibrarySearch")->setText("尾段600");check(list->count()==1,"actual full library search"); delete ui;QString large=QString("大材料正文").repeated(240000);auto big=descriptor("docs","large",large);auto bigRef=materialLibrary::material(big).value("reference").toObject();auto bigRecord=materialLibrary::classification(bigRef,"人工",{},"笔记","");store.save(bigRecord,"");check(store.heads().value(materialLibrary::key(bigRef)).toObject().value("reference").toObject().value("snapshot").toObject().value("text")==large,"large classification preserves complete source");auto bigRev=store.saveState({{"notes",large}},rev);check(store.state().value("notes").toString()==large,"large private state");auto edited=bigRecord;edited["notes"]="forged";refuses([&]{materialLibrary::validate(edited);});
 MaterialLibraryStore literalStore(dir.path()+"/literal.sqlite");literalStore.save(r,"");auto literalUI=materialLibraryPage(dir.path()+"/literal.sqlite",nullptr,[=]{return QJsonArray{d};});ready(literalUI,"materialSnapshotReady");auto literalRows=literalUI->findChild<QListWidget*>("materialLibraryRows");literalRows->setCurrentRow(0);for(auto b:literalUI->findChildren<QPushButton*>())if(b->text()=="完整原文/分类")b->click();literalUI->findChild<QLineEdit*>("materialLibraryCategory")->setText("改分类保留字面标签");for(auto b:literalUI->findChildren<QPushButton*>())if(b->text()=="保存人工分类")b->click();check(literalStore.heads().value(materialLibrary::key(ref)).toObject().value("tags").toArray()==QJsonArray{"tag;literal"},"unchanged literal tags not split on category edit");literalUI->findChild<QPlainTextEdit*>("materialLibraryNotes")->setPlainText("recoverable unsaved note");delete literalUI;literalUI=materialLibraryPage(dir.path()+"/literal.sqlite",nullptr,[=]{return QJsonArray{d};});ready(literalUI,"materialSnapshotReady");check(literalUI->findChild<QPlainTextEdit*>("materialLibraryNotes")->toPlainText()=="recoverable unsaved note","actual UI draft reopen");delete literalUI;std::cout<<"PASS material library source namespace/docs identity/changed missing refusal/full601 search/manual labels/CAS/no overwrite/import cancel/history/private backup/UI; independent staging only\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}


